package kr.danta.core.nation;
import kr.danta.core.state.GameState;import kr.danta.core.territory.*;import org.junit.jupiter.api.Test;import java.time.Duration;import java.util.Map;import static org.junit.jupiter.api.Assertions.*;
class Dev097IndependenceWarServiceTest{
 private GameState game(){GameState g=new GameState();g.addNation(new NationState("red","Red","red_cap",0,NationStatus.VASSAL));g.addNation(new NationState("blue","Blue","blue_cap",0,NationStatus.ACTIVE));g.addStrategicPoint(new StrategicPoint("red_cap","Red Cap",StrategicPointType.CAPITAL,"red",new PointPosition("world",0,64,0),1,Map.of()));return g;}
 @Test void minimumPeriodAndCapitalHoldUseRuntime(){GameState g=game();VassalService v=new VassalService(g);v.restore(new VassalRelation("red","blue",0));IndependenceWarService s=new IndependenceWarService(g,v,Duration.ofHours(1),Duration.ofMinutes(10),Duration.ofMinutes(30));assertThrows(IllegalStateException.class,()->s.declare("red",3599999));s.declare("red",3600000);assertEquals(IndependenceWarService.Outcome.ONGOING,s.tick("red",4199999));assertEquals(IndependenceWarService.Outcome.INDEPENDENCE_SUCCESS,s.tick("red",4200000));assertTrue(v.relation("red").isEmpty());assertEquals(NationStatus.ACTIVE,g.nation("red").orElseThrow().status());}
 @Test void losingOwnCapitalFailsAndStartsCooldown(){GameState g=game();VassalService v=new VassalService(g);v.restore(new VassalRelation("red","blue",0));IndependenceWarService s=new IndependenceWarService(g,v,Duration.ofSeconds(1),Duration.ofMinutes(10),Duration.ofMinutes(30));s.declare("red",1000);g.strategicPoint("red_cap").orElseThrow().setOwnerNationId("blue");assertEquals(IndependenceWarService.Outcome.FAILED_CAPITAL_LOST,s.tick("red",2000));assertThrows(IllegalStateException.class,()->s.declare("red",3000));}
}
